/*
// Definition for an Interval.
class Interval {
public:
    int start;
    int end;
    Interval() : start(-1), end(-1) {}
    Interval(int s, int e) : start(s), end(e) {}
};
*/
class Solution {
public:
    vector<Interval> employeeFreeTime(vector<vector<Interval>> schedule) {
        vector<Interval> ivs;
        for (auto& emp : schedule)
            for (auto& iv : emp) ivs.push_back(iv);
        sort(ivs.begin(), ivs.end(), [](const Interval& a, const Interval& b) {
            return a.start < b.start;
        });
        vector<Interval> res;
        int prevEnd = ivs[0].end;
        for (int i = 1; i < (int)ivs.size(); i++) {
            if (ivs[i].start > prevEnd)
                res.push_back(Interval(prevEnd, ivs[i].start));
            prevEnd = max(prevEnd, ivs[i].end);
        }
        return res;
    }
};

