        ivs.sort((a, b) -> Integer.compare(a.start, b.start));
        List<Interval> res = new ArrayList<>();
        int prevEnd = ivs.get(0).end;
        for (int i = 1; i < ivs.size(); i++) {
            Interval iv = ivs.get(i);
            if (iv.start > prevEnd)
                res.add(new Interval(prevEnd, iv.start));
            prevEnd = Math.max(prevEnd, iv.end);
        }
        return res;
    }
}

