class Solution {
public:
    vector<Interval> employeeFreeTime(vector<vector<Interval>> schedule) {
        using T = tuple<int,int,int>;
        priority_queue<T, vector<T>, greater<T>> pq;
        for (int i = 0; i < (int)schedule.size(); i++)
            pq.push({schedule[i][0].start, i, 0});
        vector<Interval> res;
        auto [s0, i0, j0] = pq.top();
        int prevEnd = schedule[i0][j0].end;
        while (!pq.empty()) {
            auto [s, i, j] = pq.top(); pq.pop();
            const Interval& iv = schedule[i][j];
            if (iv.start > prevEnd)
                res.push_back(Interval(prevEnd, iv.start));
            prevEnd = max(prevEnd, iv.end);
            if (j + 1 < (int)schedule[i].size())
                pq.push({schedule[i][j+1].start, i, j + 1});
        }
        return res;
    }
};

