class Solution {
    public List<Interval> employeeFreeTime(List<List<Interval>> schedule) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) ->
            Integer.compare(schedule.get(a[0]).get(a[1]).start,
                            schedule.get(b[0]).get(b[1]).start));
        for (int i = 0; i < schedule.size(); i++) pq.offer(new int[]{i, 0});
        List<Interval> res = new ArrayList<>();
        int[] top = pq.peek();
        int prevEnd = schedule.get(top[0]).get(top[1]).end;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            Interval iv = schedule.get(cur[0]).get(cur[1]);
            if (iv.start > prevEnd)
                res.add(new Interval(prevEnd, iv.start));
            prevEnd = Math.max(prevEnd, iv.end);
            if (cur[1] + 1 < schedule.get(cur[0]).size())
                pq.offer(new int[]{cur[0], cur[1] + 1});
        }
        return res;
    }
}

